add_action( 'pre_get_posts', 'perfectpixel_sort_admin_products_by_stock' );

function perfectpixel_sort_admin_products_by_stock( $query ) {
	global $pagenow;
	if ( ! is_admin() || 'edit.php' !== $pagenow || ! $query->is_main_query() || 'product' !== $query->get( 'post_type' ) || ! empty( $_GET['orderby'] ) ) {
		return;
	}
	// "instock" < "onbackorder" < "outofstock" alphabetically.
	$query->set( 'meta_key', '_stock_status' );
	$query->set( 'orderby', array( 'meta_value' => 'ASC', 'title' => 'ASC' ) );
}
